   if(kind==EffectKind936.Traînée_lumineuse&&frames.Count>0)MaxLight(source,result,Math.Min(.95,Math.Abs(value)/100));
   int smallW=Math.Min(640,w),smallH=Math.Max(1,h*smallW/w);var saved=new Bitmap(smallW,smallH,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(saved))g.DrawImage(kind==EffectKind936.Rémanence||kind==EffectKind936.Traînée_lumineuse?result:source,new Rectangle(0,0,smallW,smallH));frames.Enqueue(saved);while(frames.Count>(kind==EffectKind936.Échos?3:1))frames.Dequeue().Dispose();source.Dispose();return result;
  }
  static unsafe void MaxLight(Bitmap source,Bitmap result,double strength){var r=new Rectangle(0,0,source.Width,source.Height);var a=source.LockBits(r,ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);var b=result.LockBits(r,ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{for(int y=0;y<r.Height;y++){byte* p=(byte*)a.Scan0+y*a.Stride,q=(byte*)b.Scan0+y*b.Stride;for(int x=0;x<r.Width;x++)for(int c=0;c<3;c++)q[x*4+c]=(byte)Math.Max(p[x*4+c],q[x*4+c]*strength);}}finally{source.UnlockBits(a);result.UnlockBits(b);}}
  public void Dispose(){foreach(var f in frames)f.Dispose();frames.Clear();}
 }
